namespace ImageGenerator.Models;

public sealed record UploadedImage
{
    public required string Name { get; init; }

    public required string ContentType { get; init; }

    /// <summary>Object URL generated by the browser (blob: scheme). Used for &lt;img&gt; src.</summary>
    public required string ObjectUrl { get; init; }

    /// <summary>Image bytes fetched from the browser when submitting to the API.</summary>
    public byte[] Data { get; set; } = [];
}
